import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.13;renderer.outputColorSpace=THREE.SRGBColorSpace;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9caeae);scene.fog=new THREE.FogExp2(0x9caeae,.00145);
const camera=new THREE.PerspectiveCamera(62,innerWidth/innerHeight,.1,900);
const hemi=new THREE.HemisphereLight(0xc9e4ee,0x35403b,2.1);scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffddb0,3.2);sun.position.set(-90,125,65);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-160;sun.shadow.camera.right=160;sun.shadow.camera.top=160;sun.shadow.camera.bottom=-160;sun.shadow.bias=-.00015;scene.add(sun);
const fill=new THREE.DirectionalLight(0x7ac4c3,.65);fill.position.set(80,40,-90);scene.add(fill);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const asphalt=mat(0x252c2d),sidewalk=mat(0x858681),concrete=mat(0x65706b),white=mat(0xd8d8c8),dark=mat(0x182122,.55),glass=new THREE.MeshStandardMaterial({color:0x78a6a8,roughness:.22,metalness:.45,emissive:0x152729,emissiveIntensity:.3}),neon=new THREE.MeshStandardMaterial({color:0xc9ef75,emissive:0x9fca3c,emissiveIntensity:1.6}),redNeon=new THREE.MeshStandardMaterial({color:0xf07862,emissive:0xc54439,emissiveIntensity:1.5});
const boxGeo=new THREE.BoxGeometry(1,1,1),sphereGeo=new THREE.SphereGeometry(1,12,10),cylGeo=new THREE.CylinderGeometry(1,1,1,10);
function box(parent,x,y,z,sx,sy,sz,material,cast=false,receive=true){const m=new THREE.Mesh(boxGeo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=cast;m.receiveShadow=receive;parent.add(m);return m}
function sphere(parent,x,y,z,r,material){const m=new THREE.Mesh(sphereGeo,material);m.position.set(x,y,z);m.scale.set(r,r,r);parent.add(m);return m}
function cylinder(parent,x,y,z,r,h,material,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r*.83,r,h,segments),material);m.position.set(x,y,z);parent.add(m);return m}
const world=new THREE.Group();scene.add(world);
// Coastal ground and the walkable city grid
box(world,0,-.52,0,410,1,410,mat(0x697f78));
box(world,0,-.34,195,410,.4,35,mat(0x397d82));
const roadPositions=[];for(let p=-175;p<=175;p+=50)roadPositions.push(p);
for(const p of roadPositions){box(world,p,.015,0,8,.08,360,asphalt);box(world,0,.016,p,360,.08,8,asphalt);
  box(world,p-5,.05,0,2,.15,360,sidewalk);box(world,p+5,.05,0,2,.15,360,sidewalk);box(world,0,.05,p-5,360,.15,2,sidewalk);box(world,0,.05,p+5,360,.15,2,sidewalk);
  for(let n=-170;n<175;n+=12){box(world,p,.07,n, .11,.025,4,mat(0xd4cfae));box(world,n,.07,p,4,.025,.11,mat(0xd4cfae));}
}
// Block-by-block skyline, varied by neighborhood
let seed=74129;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}function range(a,b){return a+(b-a)*rand()}
const buildingMats=[0x49585a,0x646b68,0x7b786e,0x475357,0x8c8779,0x385158,0x6a7470].map(c=>mat(c,.72,.12));
const windowMat=new THREE.MeshStandardMaterial({color:0xe9d395,emissive:0xc29550,emissiveIntensity:.36,roughness:.38});
for(let ix=0;ix<7;ix++)for(let iz=0;iz<7;iz++){
 const bx=-150+ix*50,bz=-150+iz*50;
 const dist=Math.hypot(bx+20,bz+20);const downtown=dist<95;const district=ix<2?'old':iz>4?'beach':ix>4?'industrial':'central';
 const count=downtown?range(2,4):range(1,3);
 for(let j=0;j<count;j++){
  const w=range(downtown?13:15,downtown?23:27),d=range(13,25),x=bx+range(-10,10),z=bz+range(-10,10);
  let h=range(12,downtown?66:34);if(district==='industrial')h*=.7;if(district==='beach')h=Math.min(h,23);
  const g=new THREE.Group();g.position.set(x,0,z);world.add(g);const bm=buildingMats[Math.floor(rand()*buildingMats.length)];
  box(g,0,h/2,0,w,h,d,bm,true);
  // reflective vertical window bands and roof details
  const floors=Math.floor(h/3.5),cols=Math.max(2,Math.floor(w/3.2));
  for(let f=1;f<floors;f++)for(let c=0;c<cols;c++){
   if(rand()<.13)continue;const wx=-w/2+((c+.5)*w/cols);
   box(g,wx,f*3.35, d/2+.015,w/cols*.53,1.35,.035,rand()<.13?windowMat:glass);
   if(rand()<.65)box(g,wx,f*3.35,-d/2-.015,w/cols*.53,1.35,.035,glass);
  }
  if(downtown&&h>38){box(g,0,h+.5,0,w*.38,1.1,d*.4,mat(0x364346),true);box(g,0,h+1.12,0,w*.22,.12,d*.22,neon);}
  if(district==='beach'&&j===0){box(g,0,h+.5,0,w*.8,.5,d*.75,mat(0xc3b08a));}
  // street-facing entrance awning
  box(g,0,3.2,d/2+.65,w*.6,.22,1.2,j%2?redNeon:neon);
  if(rand()<.35){const sign=box(g,w*.38,4,d/2+.08,1.1,3,.12,district==='old'?redNeon:neon);sign.rotation.z=.05;}
  for(let side of [-1,1])box(g,side*(w/2-.4),h/2,d/2+.05,.18,h*.9,.12,mat(0x9daca5,.35,.3));
 }
 // landscaped central islands, palms and street furniture
 if(rand()<.65){box(world,bx, .24,bz,8,.35,8,mat(0x65786b));for(let k=0;k<4;k++){const tx=bx+range(-2.8,2.8),tz=bz+range(-2.8,2.8);cylinder(world,tx,2.2,tz,.25,4,mat(0x665342));for(let q=0;q<5;q++){const a=q*1.25;const leaf=box(world,tx+Math.cos(a)*1.5,4.2+Math.sin(a*.7)*.4,tz+Math.sin(a)*1.5,.23,.2,2.2,mat(0x3e7054));leaf.rotation.y=a;leaf.rotation.z=-.22;}}}
}
// Lane lamps, signs, benches and driveable-cover props
const coverObjects=[];
for(const p of roadPositions)for(let n=-150;n<=150;n+=50){
 for(const side of [-1,1]){const x=p+side*7.1,z=n+3;box(world,x,2.5,z,.15,5,.15,dark);box(world,x,5,z,.85,.16,.28,mat(0xffe6aa,.35,0));
  const light=new THREE.PointLight(0xffd49a,7,17,2);light.position.set(x,4.8,z);scene.add(light);
 }
}
for(let i=0;i<32;i++){const x=range(-165,165),z=range(-165,165);if(Math.abs((x+25)%50)<8||Math.abs((z+25)%50)<8)continue;const c=box(world,x,.7,z,range(1.3,2.5),1.4,range(1,2),concrete,true);coverObjects.push(c);}
// Oceanfront promenade
for(let i=-190;i<200;i+=12){box(world,i,.35,177,1,.7,.35,mat(0xd6d0bc));box(world,i,1.1,177,.15,.15,.15,mat(0x54645d));}
const water=new THREE.Mesh(new THREE.PlaneGeometry(410,100,1,1),new THREE.MeshStandardMaterial({color:0x397c83,roughness:.24,metalness:.32}));water.rotation.x=-Math.PI/2;water.position.set(0,-.05,235);scene.add(water);

