water.position.set(0,-.05,235);scene.add(water);

// Player, third-person vehicle handling and street life
const player=new THREE.Group();scene.add(player);player.position.set(-7,0,8);
const skin=mat(0xc58a68),jacket=mat(0x263839),pants=mat(0x252b2a),shoe=mat(0x111515),hair=mat(0x251d1a);
const torso=box(player,0,1.34,0,.62,.78,.34,jacket,true),head=sphere(player,0,1.93,0,.22,skin);head.scale.set(.22,.27,.22);sphere(player,0,2.13,-.015,.19,hair).scale.set(.22,.09,.22);
const legs=[];for(const side of [-1,1]){const leg=box(player,side*.17,.65,0,.23,.68,.26,pants,true);legs.push(leg);box(player,side*.18,.18,.045,.27,.2,.4,shoe,true);const arm=box(player,side*.39,1.38,0,.2,.63,.22,jacket,true);arm.rotation.z=side*.09;}
const gun=box(player,.35,1.25,-.42,.13,.14,.56,dark);const playerShadow=new THREE.Mesh(new THREE.CircleGeometry(.65,20),new THREE.MeshBasicMaterial({color:0x101514,transparent:true,opacity:.32}));playerShadow.rotation.x=-Math.PI/2;playerShadow.position.y=.045;player.add(playerShadow);
const cars=[],carColors=[0x9ca7a1,0x263d45,0xb7b4a1,0x7d352d,0xc1aa63,0x2d3b39,0x495d6a];
function makeCar(x,z,angle,color=carColors[Math.floor(rand()*carColors.length)],isBike=false){const root=new THREE.Group();root.position.set(x,.04,z);root.rotation.y=angle;world.add(root);const body=mat(color,.3,.62);box(root,0,.52,0,isBike?.65:2.05,.48,isBike?2.2:4.15,body,true);if(!isBike){box(root,0,.98,-.28,1.55,.62,1.85,glass,true);box(root,0,.27,0,2.12,.16,4.2,dark);for(const xx of [-.9,.9])for(const zz of [-1.35,1.35]){const wh=cylinder(root,xx,.32,zz,.34,.2,dark,14);wh.rotation.z=Math.PI/2;box(root,xx,.34,zz+(zz<0?-.015:.015),.15,.42,.3,mat(0x232627));}for(const xx of [-.75,.75]){box(root,xx,.57,2.06,.38,.16,.08,mat(0xffedb5,.25));box(root,xx,.55,-2.07,.35,.15,.07,redNeon);}}else{cylinder(root,0,.4,-.78,.42,.16,dark,14).rotation.z=Math.PI/2;cylinder(root,0,.4,.78,.42,.16,dark,14).rotation.z=Math.PI/2;box(root,0,.83,0,.36,.38,.95,body,true);cylinder(root,0,.82,-.1,.08,.75,dark,8).rotation.x=Math.PI/2;}
 const wheels=[];root.traverse(o=>{if(o.geometry&&o.geometry.type==='CylinderGeometry')wheels.push(o)});const car={root,speed:0,angle,colors:color,isBike,wheels};cars.push(car);return car;}
const playerCar=makeCar(-9,12,Math.PI,0x4e8a82);makeCar(1,12,Math.PI,0xb4b7aa);makeCar(-120,-72,0,0x873c32,true);
const traffic=[];for(let i=0;i<20;i++){const lane=roadPositions[Math.floor(rand()*roadPositions.length)]+(rand()>.5?2.7:-2.7),vertical=rand()>.5;const t=makeCar(vertical?lane:range(-170,170),vertical?range(-170,170):lane,vertical?(rand()>.5?0:Math.PI):(rand()>.5?Math.PI/2:-Math.PI/2),carColors[Math.floor(rand()*carColors.length)],rand()<.13);traffic.push({car:t,vertical,dir:t.root.rotation.y===0||t.root.rotation.y===Math.PI?1:1,base:lane});}
const pedestrianMat=[mat(0xb27955),mat(0x9aaca3),mat(0x65443f),mat(0x6a7280),mat(0xb99c65)];const pedestrians=[];
for(let i=0;i<36;i++){const p=new THREE.Group();const x=range(-160,160),z=range(-160,160);p.position.set(x,0,z);world.add(p);const color=pedestrianMat[Math.floor(rand()*pedestrianMat.length)];box(p,0,1.05,0,.38,.62,.25,color,true);sphere(p,0,1.5,0,.15,skin).scale.set(.15,.18,.15);box(p,-.11,.48,0,.12,.43,.13,pants);box(p,.11,.48,0,.12,.43,.13,pants);pedestrians.push({mesh:p,phase:rand()*8,speed:range(.45,1.15),dir:rand()*Math.PI*2,change:range(2,7)});}
// Checkpoint beacons and targets
const drones=[];const dronePlaces=[[-72,-72],[78,-72],[-72,78],[78,78],[2,-125]];
for(let i=0;i<5;i++){const g=new THREE.Group();g.position.set(dronePlaces[i][0],5,dronePlaces[i][1]);world.add(g);const orb=sphere(g,0,0,0,.42,neon);const ring=new THREE.Mesh(new THREE.TorusGeometry(.68,.035,6,24),neon);g.add(ring);const beam=new THREE.Mesh(new THREE.CylinderGeometry(.02,.7,9,16,1,true),new THREE.MeshBasicMaterial({color:0xd9f36a,transparent:true,opacity:.09,side:THREE.DoubleSide}));beam.position.y=-4.5;g.add(beam);drones.push({group:g,active:true,index:i,orb});}
// Decorative beacon indicators over unvisited targets
const keys={};addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&started)togglePause();if(e.code==='KeyF'&&started)toggleVehicle();if(e.code==='KeyQ'&&started)cover=!cover;if(e.code==='KeyR'&&started){ammo=18;showToast('CARGADOR RECARGADO');}});addEventListener('keyup',e=>keys[e.code]=false);
let started=false,paused=false,cover=false,inVehicle=false,ammo=18,health=100,clockSeconds=18*3600+42*60,shotCooldown=0,toastTimer=0,lookYaw=0,lookPitch=.19,mouseDown=false,objectiveCount=0;
const startScreen=document.querySelector('#start-screen'),pauseOverlay=document.querySelector('#pause-overlay'),crosshair=document.querySelector('#crosshair'),vehicleHud=document.querySelector('#vehicle-hud'),coverIndicator=document.querySelector('#cover-indicator'),toast=document.querySelector('#toast'),interaction=document.querySelector('#interaction');
document.querySelector('#start-button').onclick=()=>{started=true;startScreen.classList.add('hidden');document.querySelector('#controls-hint').style.opacity='.6';renderer.domElement.requestPointerLock?.();showToast('BIENVENIDO A NEON COAST');};document.querySelector('#resume-button').onclick=()=>togglePause();
function togglePause(){paused=!paused;pauseOverlay.classList.toggle('hidden',!paused);if(paused)document.exitPointerLock?.();else renderer.domElement.requestPointerLock?.();}
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas){lookYaw-=e.movementX*.0022;lookPitch=THREE.MathUtils.clamp(lookPitch+e.movementY*.0018,-.12,.55);}});
function toggleVehicle(){if(!inVehicle){let nearest=null,dist=4;for(const c of cars){const d=c.root.position.distanceTo(player.position);if(d<dist){nearest=c;dist=d;}}if(nearest){currentCar=nearest;inVehicle=true;player.visible=false;vehicleHud.classList.remove('hidden');crosshair.classList.add('hidden');showToast(nearest.isBike?'MOTOCICLETA LISTA':'VEHÍCULO LISTO');}else showToast('ACÉRCATE A UN VEHÍCULO');}else{inVehicle=false;player.visible=true;vehicleHud.classList.add('hidden');player.position.copy(currentCar.root.position);player.position.x+=Math.cos(currentCar.root.rotation.y)*2.1;player.position.z-=Math.sin(currentCar.root.rotation.y)*2.1;currentCar.speed=0;showToast('A PIE');}}
let currentCar=playerCar;
function showToast(msg){toast.textContent=msg;toast.classList.add('show');toastTimer=2.2;}
function clampCity(pos){pos.x=THREE.MathUtils.clamp(pos.x,-178,178);pos.z=THREE.MathUtils.clamp(pos.z,-178,178);}
function collideBuildings(pos,r=.6){for(const b of colliders){const nx=THREE.MathUtils.clamp(pos.x,b.x-b.w/2-r,b.x+b.w/2+r),nz=THREE.MathUtils.clamp(pos.z,b.z-b.d/2-r,b.z+b.d/2+r);if(Math.abs(pos.x-nx)<r&&Math.abs(pos.z-nz)<r&&pos.y<b.h+1.2)return true;}return false;}
function updatePlayer(dt,t){if(inVehicle){const c=currentCar;let throttle=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),steer=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);if(keys.Space)c.speed*=Math.max(0,1-dt*3.2);c.speed+=throttle*(c.isBike?18:13)*dt;c.speed*=Math.pow(.985,dt*60);c.speed=THREE.MathUtils.clamp(c.speed,-9,c.isBike?38:32);c.root.rotation.y-=steer*dt*(.9+Math.abs(c.speed)*.035)*Math.sign(c.speed||1);const nx=c.root.position.x-Math.sin(c.root.rotation.y)*c.speed*dt,nz=c.root.position.z-Math.cos(c.root.rotation.y)*c.speed*dt;const next=new THREE.Vector3(nx,0,nz);if(!collideBuildings(next,c.isBike?.55:1.2)){c.root.position.x=nx;c.root.position.z=nz;}else{c.speed*=-.27;}clampCity(c.root.position);for(const w of c.wheels)w.rotation.x+=c.speed*dt*1.5;document.querySelector('#speed-value').textContent=String(Math.abs(Math.round(c.speed*3.6))).padStart(3,'0');document.querySelector('#speed-lines').classList.toggle('active',Math.abs(c.speed)>14);return;}
