content.text:
.vehicle-hud.hidden { display:none }
.interaction { position:absolute;z-index:5;left:50%;bottom:20%;transform:translateX(-50%);font-size:11px;letter-spacing:1px;text-shadow:0 2px 6px #000;white-space:nowrap }
.interaction b { display:inline-grid;place-items:center;width:22px;height:22px;border:1px solid #d9f36a;color:#d9f36a;margin-right:8px;font:700 12px 'Barlow Condensed' }
.crosshair { position:absolute;z-index:5;left:50%;top:50%;width:25px;height:25px;transform:translate(-50%,-50%);pointer-events:none }
.crosshair i { position:absolute;background:#e4f0dc;box-shadow:0 0 4px #172020 }
.crosshair i:nth-child(1) { height:6px;width:1px;left:12px;top:0 }
.crosshair i:nth-child(2) { height:6px;width:1px;left:12px;bottom:0 }
.crosshair i:nth-child(3) { width:6px;height:1px;left:0;top:12px }
.crosshair i:nth-child(4) { width:6px;height:1px;right:0;top:12px }
.crosshair b { position:absolute;width:3px;height:3px;border-radius:50%;background:#d9f36a;left:11px;top:11px }
.crosshair.hidden { display:none }
.cover-indicator { position:absolute;left:50%;bottom:24%;transform:translateX(-50%);font-size:9px;letter-spacing:2px;color:#d9f36a;opacity:0;transition:opacity .2s }
.cover-indicator.active { opacity:1 }
.cover-indicator span { margin-right:7px }
.toast { position:absolute;top:86px;left:50%;transform:translate(-50%,-12px);opacity:0;padding:9px 18px;background:#111b1bdb;border-bottom:1px solid #d9f36a;color:#e5ebe4;font-size:10px;letter-spacing:1px;z-index:7;transition:all .3s;pointer-events:none }
.toast.show { opacity:1;transform:translate(-50%,0) }
.toast-stack { position:absolute;right:39px;top:105px;z-index:4 }
.pause-overlay.hidden { display:none }
.start-screen.hidden { display:none }

